jest.mock("../../lib/authApi", () => {
  const actual = jest.requireActual("../../lib/authApi");
  return {
    ...actual,
    authFetch: jest.fn(),
  };
});

import { API_BASE_URL } from "@/lib/api";
import { sum } from "@/lib/sum";
import { getSaToken, setSaToken, clearSaToken, isSaAuthenticated } from "@/lib/superAdminAuth";
import { authFetch } from "@/lib/authApi";
import * as adminApi from "@/lib/adminApi";
import * as candidateApi from "@/lib/candidateApi";
import * as changeRequestApi from "@/lib/changeRequestApi";
import * as cnbAdminApi from "@/lib/cnbAdminApi";
import * as hrDirectoryApi from "@/lib/hrDirectoryApi";
import * as notificationsApi from "@/lib/notificationsApi";
import * as superAdminApi from "@/lib/superAdminApi";

const response = (body: unknown, init: { status?: number } = {}) =>
  ({
    ok: (init.status ?? 200) >= 200 && (init.status ?? 200) < 300,
    status: init.status ?? 200,
    json: async () => body,
    text: async () => (typeof body === "string" ? body : JSON.stringify(body)),
  } as Response);

describe("small helpers", () => {
  it("handles super-admin auth tokens and math helpers", () => {
    clearSaToken();
    expect(isSaAuthenticated()).toBe(false);
    setSaToken("token-1");
    expect(getSaToken()).toBe("token-1");
    expect(isSaAuthenticated()).toBe(true);
    expect(superAdminApi.saApi.defaults.baseURL).toBeDefined();
    clearSaToken();
    expect(isSaAuthenticated()).toBe(false);
    expect(sum(2, 3)).toBe(5);
    expect(API_BASE_URL).toContain("/api/");
  });
});

describe("notifications api", () => {
  beforeEach(() => {
    localStorage.clear();
    jest.restoreAllMocks();
    global.fetch = jest.fn();
  });

  it("gets and marks notifications", async () => {
    localStorage.setItem("access_token", "abc");
    (global.fetch as jest.Mock)
      .mockResolvedValueOnce(response([{ notification_id: "n1" }]))
      .mockResolvedValueOnce(response({}))
      .mockResolvedValueOnce(response({}));

    await expect(notificationsApi.getMyNotifications()).resolves.toEqual([{ notification_id: "n1" }]);
    await expect(notificationsApi.markNotificationRead("n1")).resolves.toBeUndefined();
    await expect(notificationsApi.markAllNotificationsRead()).resolves.toBeUndefined();
  });
});

describe("admin, candidate, change request, directory, and cnb admin apis", () => {
  beforeEach(() => {
    jest.restoreAllMocks();
    (authFetch as jest.Mock).mockReset();
  });

  it("covers common admin endpoints", async () => {
    (authFetch as jest.Mock)
      .mockResolvedValueOnce(response([{ user_id: "u1" }]))
      .mockResolvedValueOnce(response({ total: 1 }))
      .mockResolvedValueOnce(response({ user: { user_id: "u1" }, signup_link: "link", expires_at: "now" }))
      .mockResolvedValueOnce(response({}))
      .mockResolvedValueOnce(response({}))
      .mockResolvedValueOnce(response({}))
      .mockResolvedValueOnce(response([{ company_id: "c1" }]))
      .mockResolvedValueOnce(response([{ subscription_id: "s1" }]))
      .mockResolvedValueOnce(response({ active: 1 }))
      .mockResolvedValueOnce(response([{ plan: "Starter" }]))
      .mockResolvedValueOnce(response({ success: true }))
      .mockResolvedValueOnce(response([{ module_id: "m1" }]))
      .mockResolvedValueOnce(response({ success: true }))
      .mockResolvedValueOnce(response(["HR", "IT"]));

    await expect(adminApi.getUsers()).resolves.toEqual([{ user_id: "u1" }]);
    await expect(adminApi.getUserStats()).resolves.toEqual({ total: 1 });
    await expect(adminApi.createUser({
      first_name: "Ada",
      last_name: "Lovelace",
      username: "ada",
      email: "ada@example.com",
      role: "Admin",
      department: "HR",
      company_id: "c1",
      start_date: "2026-01-01",
      link_expiry_hours: 24,
    })).resolves.toMatchObject({ signup_link: "link" });
    await expect(adminApi.setUserStatus("u1", "active")).resolves.toBeUndefined();
    await expect(adminApi.updateUser("u1", { first_name: "Grace" })).resolves.toBeUndefined();
    await expect(adminApi.resendSignupLink("u1", 24)).resolves.toBeUndefined();
    await expect(adminApi.getCompanies()).resolves.toEqual([{ company_id: "c1" }]);
    await expect(adminApi.getSubscriptions()).resolves.toEqual([{ subscription_id: "s1" }]);
    await expect(adminApi.getBillingStats()).resolves.toEqual({ active: 1 });
    await expect(adminApi.getPlans()).resolves.toEqual([{ plan: "Starter" }]);
    await expect(adminApi.updateSubscription("s1", { status: "active" } as never)).resolves.toBeUndefined();
    await expect(adminApi.getLifecyclePermissions()).resolves.toEqual([{ module_id: "m1" }]);
    await expect(adminApi.saveLifecyclePermissions([{ module_id: "m1" } as never])).resolves.toBeUndefined();
    await expect(adminApi.getDepartments()).resolves.toEqual(["HR", "IT"]);
  });

  it("covers candidate and change request flows", async () => {
    (authFetch as jest.Mock)
      .mockResolvedValueOnce(response([{ job_posting_id: "j1" }]))
      .mockResolvedValueOnce(response({ job_posting_id: "j1", candidates: [] }))
      .mockResolvedValueOnce(response({ message: "saved", job_posting_id: "j1", updated_count: 1 }))
      .mockResolvedValueOnce(response({ message: "updated" }))
      .mockResolvedValueOnce(response([{ request_id: "cr1" }]))
      .mockResolvedValueOnce(response([{ request_id: "cr2" }]))
      .mockResolvedValueOnce(response([{ request_id: "cr3" }]))
      .mockResolvedValueOnce(response({ request_id: "cr4" }));

    await expect(candidateApi.getCandidateJobs()).resolves.toEqual([{ job_posting_id: "j1" }]);
    await expect(candidateApi.getRankedCandidates("j1", "sfia")).resolves.toMatchObject({ job_posting_id: "j1" });
    await expect(candidateApi.saveManualRanking("j1", [{ application_id: "a1", rank: 1 }])).resolves.toMatchObject({
      updated_count: 1,
    });
    (global.fetch as jest.Mock) = jest.fn().mockResolvedValue(response({ surveyScore: 87 }));
    await expect(candidateApi.getSurveyScore("a1")).resolves.toEqual({ surveyScore: 87 });
    await expect(candidateApi.updateApplicationStatus("a1", "approved")).resolves.toEqual({ message: "updated" });

    await expect(changeRequestApi.getMyChangeRequests()).resolves.toEqual([{ request_id: "cr1" }]);
    await expect(changeRequestApi.getHRChangeRequests("pending")).resolves.toEqual([{ request_id: "cr2" }]);
    await expect(changeRequestApi.submitChangeRequest({
      field_type: "bank",
      requested_changes: { bank_name: "ACME" },
      reason: "update",
    })).resolves.toMatchObject({ request_id: "cr4" });
    await expect(changeRequestApi.reviewChangeRequest("cr4", { status: "approved", review_reason: "ok" })).resolves.toEqual({
      request_id: "cr4",
    });
  });

  it("covers cnb admin and hr directory endpoints", async () => {
    (authFetch as jest.Mock)
      .mockResolvedValueOnce(response({ tenant: true }))
      .mockResolvedValueOnce(response({ tenant: true }))
      .mockResolvedValueOnce(response({ config: true }))
      .mockResolvedValueOnce(response({ config: true }))
      .mockResolvedValueOnce(response([{ bracket_id: "b1" }]))
      .mockResolvedValueOnce(response({ bracket_id: "b1" }))
      .mockResolvedValueOnce(response({}))
      .mockResolvedValueOnce(response([{ user_id: "u1" }]))
      .mockResolvedValueOnce(response({ user_id: "u1" }))
      .mockResolvedValueOnce(response([{ user_id: "u1" }]))
      .mockResolvedValueOnce(response([{ role_id: "r1" }]))
      .mockResolvedValueOnce(response([{ department_id: "d1" }]))
      .mockResolvedValueOnce(response({
        users: [{ user_id: "u1" }],
        roles: [{ role_id: "r1" }],
        departments: [{ department_id: "d1" }],
      }))
      .mockResolvedValueOnce(response({ user_id: "u1" }));

    await expect(cnbAdminApi.getTenantPayrollConfig()).resolves.toEqual({ tenant: true });
    await expect(cnbAdminApi.updateTenantPayrollConfig({} as never)).resolves.toEqual({ tenant: true });
    await expect(cnbAdminApi.getStatutoryDeductionConfig()).resolves.toEqual({ config: true });
    await expect(cnbAdminApi.saveStatutoryDeductionConfig({} as never)).resolves.toEqual({ config: true });
    await expect(cnbAdminApi.getTaxBrackets(2026)).resolves.toEqual([{ bracket_id: "b1" }]);
    await expect(cnbAdminApi.createTaxBracket({} as never)).resolves.toMatchObject({ bracket_id: "b1" });
    await expect(cnbAdminApi.deleteTaxBracket("b1")).resolves.toBeUndefined();

    await expect(hrDirectoryApi.getDirectorySnapshot()).resolves.toMatchObject({
      users: [{ user_id: "u1" }],
      roles: [{ role_id: "r1" }],
      departments: [{ department_id: "d1" }],
    });
    await expect(hrDirectoryApi.updateDirectoryUser("u1", { first_name: "Ada" } as never)).resolves.toEqual({ user_id: "u1" });
  });
});
